/// <summary>
/// Everything one record has accumulated, in one read.
///
/// The enrichment is deliberately NOT here. It has its own operation already, answering
/// `TrackEnrichmentDetail` with every provider's payload and the station's own sourced claims, and
/// the console draws it through the same panel the list uses. One enrichment shape rather than two.
/// </summary>
public sealed record TrackDetail
{
    [JsonPropertyName("id")]
    public required Guid Id { get; init; }

    [JsonPropertyName("title")]
    public required string Title { get; init; }

    [JsonPropertyName("artistId")]
    public required Guid ArtistId { get; init; }

    [JsonPropertyName("artistName")]
    public required string ArtistName { get; init; }

    /// <summary>Absent on a single ingested outside any release: `tracks.album_id` is nullable</summary>
    [JsonPropertyName("albumId")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Guid? AlbumId { get; init; }

    [JsonPropertyName("albumName")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? AlbumName { get; init; }

    /// <summary>The record's cover, in the two spellings `Album.imageUrl` has. Nothing hangs art off a recording</summary>
    [JsonPropertyName("albumImageUrl")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? AlbumImageUrl { get; init; }

    /// <summary>Display credit as written on the release ("X feat. Y"), not a join key</summary>
    [JsonPropertyName("artists")]
    public required string Artists { get; init; }

    [JsonPropertyName("genre")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Genre { get; init; }

    [JsonPropertyName("year")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? Year { get; init; }

    [JsonPropertyName("durationMs")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public long? DurationMs { get; init; }

    [JsonPropertyName("rating")]
    public Rating Rating { get; init; } = Rating.Neutral;

    [JsonPropertyName("bindings")]
    public required List<TrackBinding> Bindings { get; init; }

    /// <summary>Absent for a record the walk has not reached</summary>
    [JsonPropertyName("analysis")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public TrackAnalysis? Analysis { get; init; }

    /// <summary>The most recent airings, newest first</summary>
    [JsonPropertyName("plays")]
    public required List<TrackPlay> Plays { get; init; }

    /// <summary>How many times in all, which the list above is only the head of</summary>
    [JsonPropertyName("playCount")]
    public required long PlayCount { get; init; }
}

