/// <summary>
/// One provider's stored answer. `found: false` is a recorded miss, which is a fact rather than a
/// failure: the provider was asked, had nothing, and is not asked again until `expiresAt`. A provider
/// that could not be asked at all is `failed` instead, and the two never both hold.
/// </summary>
public sealed record TrackEnrichmentSource
{
    [JsonPropertyName("provider")]
    public required string Provider { get; init; }

    /// <summary>The id it was fetched under. Provenance, not identity</summary>
    [JsonPropertyName("providerRef")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ProviderRef { get; init; }

    [JsonPropertyName("fetchedAt")]
    public required DateTimeOffset FetchedAt { get; init; }

    [JsonPropertyName("expiresAt")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public DateTimeOffset? ExpiresAt { get; init; }

    /// <summary>Past its TTL, so the next pass will ask again</summary>
    [JsonPropertyName("stale")]
    public required bool Stale { get; init; }

    [JsonPropertyName("found")]
    public required bool Found { get; init; }

    /// <summary>The last attempt errored, so `expiresAt` is a backoff rather than a TTL</summary>
    [JsonPropertyName("failed")]
    public required bool Failed { get; init; }

    [JsonPropertyName("data")]
    public required TrackEnrichmentData Data { get; init; }
}

